// DC motor GW370 12V with encoder 200 RPM: drive via H-bridge (IN1=8, IN2=9, ENA=10) + read its built-in quadrature encoder (A=2, B=3) on Arduino Nano.
#define IN1 8
#define IN2 9
#define ENA 10
#define ENC_A 2
#define ENC_B 3

volatile long pulseCount = 0;
void handleEncoder() {
 pulseCount += (digitalRead(ENC_B) > 0) ? 1 : -1;
}

void setup() {
 Serial.begin(115200);
 pinMode(IN1, OUTPUT); pinMode(IN2, OUTPUT); pinMode(ENA, OUTPUT);
 pinMode(ENC_A, INPUT_PULLUP); pinMode(ENC_B, INPUT_PULLUP);
 attachInterrupt(digitalPinToInterrupt(ENC_A), handleEncoder, RISING);
}

void loop() {
 digitalWrite(IN1, HIGH); digitalWrite(IN2, LOW);
 analogWrite(ENA, 200);

 Serial.print("Encoder pulses: "); Serial.println(pulseCount);
 delay(200);
}",

